function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 20*Math.sin(t));
  ctx.lineTo(W/2, H/2 + 150 + 20*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 100 + 20*Math.sin(t));
  ctx.lineTo(W/2 + 50, H/2 + 100 + 20*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20*Math.cos(t), H/2 - 50 + 20*Math.sin(t));
  ctx.lineTo(W/2 + 20*Math.cos(t), H/2 - 50 + 20*Math.sin(t));
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Thoughts', W/2, H/2 - 120 + 20*Math.sin(t));
  ctx.fillText('Emotions', W/2, H/2 + 170 + 20*Math.sin(t));
  ctx.restore();
}
